const blank={property_address:"",street_number:"",street_name:"",unit_number:"",city:"",province:"ON",postal_code:"",seller_type:"INDIVIDUAL",seller_first_name:"",seller_last_name:"",seller_company_name:"",seller_representative_first_name:"",seller_representative_last_name:"",seller_name:"",seller_phone:"",seller_email:"",seller_mailing_address:"",additional_sellers:[],property_classification:"RESIDENTIAL",property_type:"RESIDENTIAL",listing_type:"SALE",asking_price:"",listing_start_date:"",listing_expiry_date:"",notes:""};
const splitPersonName=value=>{const parts=String(value||"").trim().split(/\s+/).filter(Boolean);return {first_name:parts.shift()||"",last_name:parts.join(" ")}};
const sellerIsCompany=seller=>String(seller?.seller_type||seller?.type||seller?.entity_type||"").toUpperCase()==="COMPANY"||!!String(seller?.company_name||"").trim()||/\b(INC|INCORPORATED|LTD|LIMITED|CORP|CORPORATION|LLC|HOLDINGS|LP|LLP)\.?$/i.test(String(seller?.name||seller?.seller_name||[seller?.first_name,seller?.last_name].filter(Boolean).join(" ")||"").trim());
const sellerFullName=seller=>{if(sellerIsCompany(seller)){const company=String(seller?.company_name||seller?.name||seller?.seller_name||"").trim();const rep=[seller?.representative_first_name,seller?.representative_last_name].filter(Boolean).join(" ").trim();return [company,rep?"Attn: "+rep:""].filter(Boolean).join(" — ")}return [seller?.first_name,seller?.last_name].filter(Boolean).join(" ").trim()||String(seller?.name||seller?.seller_name||"").trim()};
const sellerToForm=(seller={},fallbackName="")=>{const legacyName=String(seller?.name||seller?.seller_name||fallbackName||[seller?.first_name,seller?.last_name].filter(Boolean).join(" ")||"").trim();const company=sellerIsCompany({...seller,name:legacyName});const person=splitPersonName(legacyName);return {seller_type:company?"COMPANY":"INDIVIDUAL",first_name:String(seller?.first_name||(!company?person.first_name:"")||""),last_name:String(seller?.last_name||(!company?person.last_name:"")||""),company_name:String(seller?.company_name||(company?legacyName:"")||""),representative_first_name:String(seller?.representative_first_name||""),representative_last_name:String(seller?.representative_last_name||""),phone:String(seller?.phone||""),email:String(seller?.email||""),mailing_address:String(seller?.mailing_address||"")}};
const uniqueSellers=items=>{const seen=new Set();return (items||[]).map(item=>({...item,name:sellerFullName(item)})).filter(item=>{const key=String(item.name||"").toLowerCase().replace(/[^a-z0-9]/g,"");if(!key||seen.has(key))return false;seen.add(key);return true})};
const formatStreetAddress=(streetNumber,streetName)=>[String(streetNumber||"").trim(),String(streetName||"").trim()].filter(Boolean).join(" ");
function splitStreetAddress(address,streetNumber="",streetName=""){
 const number=String(streetNumber||"").trim(),name=String(streetName||"").trim();
 if(number||name)return {street_number:number,street_name:name};
 const raw=String(address||"").trim();
 const matched=raw.match(/^(\d+[A-Za-z]?(?:[-/]\d+[A-Za-z]?)?)\s+(.+)$/);
 return matched?{street_number:matched[1],street_name:matched[2]}:{street_number:"",street_name:raw};
}
const recoGuide={code:"RECO_INFORMATION_GUIDE",label:"RECO Information Guide",required:true};
const defaults=[{code:"LISTING_AGREEMENT",label:"Listing Agreement",required:true},{code:"MLS_DATA",label:"MLS Data / Listing Information",required:true},{code:"PROPERTY_DETAILS",label:"Property Details / Feature Sheet",required:true},{code:"SELLER_DIRECTION",label:"Seller Direction / Authorization",required:true},{code:"ID_FINTRAC",label:"Identification / FINTRAC",required:true},recoGuide,{code:"LISTING_CANCELLATION",label:"Listing Cancellation Agreement",required:false},{code:"OTHER",label:"Other Supporting Documents",required:false}];
