 async function setDocumentReviewStatus(doc,status){
  if(!isAdmin||!doc?.id)return;
  setBusy(true);setError("");setMessage("");
  const {data,error:e}=await supabase.from("dv_accounting_listing_documents").update({review_status:status,reviewed_by:user?.id||null,reviewed_at:new Date().toISOString()}).eq("id",doc.id).select().single();
  if(e){setError("Could not update document review status: "+e.message);setBusy(false);return}
  setDocs(old=>old.map(item=>item.id===doc.id?data:item));
  if(previewDocument?.id===doc.id)setPreviewDocument(data);
  const approvedDocumentType=String(data.document_type||"").trim().toUpperCase();
  const approvedRequirement=requirements.find(item=>String(item.code||"").trim().toUpperCase()===approvedDocumentType);
  const isListingCancellationDocument=/CANCEL(LATION|LED|LING)/i.test(approvedDocumentType)||/CANCEL(LATION|LED|LING)/i.test(String(approvedRequirement?.label||""))||/CANCEL(LATION|LED|LING)/i.test(String(data.document_name||""));
  if(status==="APPROVED"&&isListingCancellationDocument){
   const listing=selected;
   if(!listing?.id){setError("Cancellation document approved, but no listing is selected to cancel.");setBusy(false);return}
   const cancellationNote="Listing cancelled after admin approval of the seller-signed listing cancellation document.";
   const {data:cancelledListing,error:cancelError}=await supabase.from("dv_accounting_listing_submissions").update({status:"CANCELLED",admin_notes:[String(listing.admin_notes||"").trim(),cancellationNote].filter(Boolean).join("\n"),reviewed_by:user?.id||null,reviewed_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq("id",listing.id).select().single();
   if(cancelError){setError("Cancellation document approved, but the listing status could not be changed: "+cancelError.message);setBusy(false);return}
   setRows(old=>old.map(row=>row.id===cancelledListing.id?cancelledListing:row));
   setSelected(cancelledListing);setForm({...blank,...cancelledListing});
   setMessage("Listing cancellation document approved. The listing is now CANCELLED.");
  }else setMessage(status==="APPROVED"?"Document approved.":status==="PENDING"?"Document marked pending.":"Document marked not approved.");
  setBusy(false);
 }
