  setBusy(true);setError("");setMessage("");
  const {data,error:e}=await supabase.from("dv_accounting_listing_submissions").update({status,mls_number:status==="PUBLISHED"?mlsNumber.trim():(selected.mls_number||null),listing_start_date:form.listing_start_date||selected.listing_start_date||null,listing_expiry_date:form.listing_expiry_date||selected.listing_expiry_date||null,admin_notes:adminNotes,reviewed_by:user?.id||null,reviewed_at:new Date().toISOString(),published_at:status==="PUBLISHED"?new Date().toISOString():selected.published_at||null,updated_at:new Date().toISOString()}).eq("id",selected.id).select().single();
  if(e){setError("Could not update listing: "+e.message);setBusy(false);return}
