    const {data,error}=await supabase.functions.invoke("trust-account-information",{body:{action,trustTransactionId:item.trust_transaction_id||item.id,rejectionReason}});
    if(error)throw error;if(data?.error)throw new Error(data.error);
    setMessage(data?.message||"Receipt review completed.");
