async function emailListingDepositReceipt(item){
   const recipientInput=window.prompt("Enter one or more recipient email addresses, separated by commas or new lines:");
   if(recipientInput===null)return;
   const recipientEmails=[...new Set(recipientInput.split(/[;,\s]+/).map(value=>value.trim().toLowerCase()).filter(Boolean))];
   if(!recipientEmails.length||recipientEmails.length>20||recipientEmails.some(email=>!/^([^\s@]+)@([^\s@]+)\.[^\s@]+$/.test(email))){setDepositError("Enter between 1 and 20 valid email addresses, separated by commas or new lines.");return}
   if(!["ADMIN","SUPERADMIN","MANAGER","STAFF"].includes(receiptIssuerProfile.role)){setDepositError("Only authorized brokerage staff can email deposit receipts.");return}
   setDepositError("");setMessage("");setDepositEmailBusy(true);
   try{
    const {data,error}=await supabase.functions.invoke("trust-account-information",{body:{action:"send_deposit_receipt",trustTransactionId:item.trust_transaction_id||item.id,recipientEmails}});
    if(error)throw error;if(data?.error)throw new Error(data.error);
    setMessage(data?.message||"Deposit receipt email request completed.");
    await loadDepositHistory(selected.id);
   }catch(err){
    let detail=err?.message||"Could not email the deposit receipt.";
    try{
     const response=err?.context;
     if(response&&typeof response.clone==="function"){
      const payload=await response.clone().json();
      if(payload?.error)detail=payload.error;
      else if(payload?.message)detail=payload.message;
     }
    }catch{}
    setDepositError(detail);
   }
   finally{setDepositEmailBusy(false)}
  }
async function loadDepositHistory(listingId){
  if(!listingId||!supabase){setDepositHistory([]);setDepositEmailLogs([]);return}
  setDepositHistoryLoading(true);setDepositHistoryError("");
  try{
   const {data:txRows,error:txError}=await supabase.from("dv_accounting_transactions").select("*").eq("listing_id",listingId).order("created_at",{ascending:false});
   if(txError)throw txError;
   const transactions=txRows||[];
   if(!transactions.length){setDepositHistory([]);setDepositEmailLogs([]);return}
   const ids=transactions.map(t=>t.id).filter(Boolean);
   const [{data:trustRows,error:trustError},{data:bankRows,error:bankError},{data:ledgerRows,error:ledgerError},{data:issuanceRows,error:issuanceError},{data:emailRows,error:emailError}]=await Promise.all([
    supabase.from("dv_accounting_transaction_trust").select("*").in("transaction_id",ids),
    supabase.from("dv_accounting_bank_accounts").select("id,name,account_number_last4").eq("account_type","REAL_ESTATE_TRUST"),
    supabase.from("dv_accounting_trust_transactions").select("*").in("transaction_id",ids).eq("direction","DEPOSIT").eq("trust_account_type","REAL_ESTATE_TRUST").eq("status","POSTED").order("ledger_date",{ascending:false}).order("created_at",{ascending:false}),
    supabase.from("dv_accounting_deposit_receipt_issuances").select("trust_transaction_id,issued_by,issuer_name,issuer_signature_path,issued_at,approval_status,approved_by,approved_at,rejection_reason").in("transaction_id",ids),
    supabase.from("dv_accounting_email_log").select("id,transaction_id,trust_transaction_id,recipient_email,subject,status,error_message,sent_by_email,sent_at,created_at,attachment_name").eq("document_type","DEPOSIT_RECEIPT").in("transaction_id",ids).order("created_at",{ascending:false})
   ]);
   if(trustError)throw trustError;if(bankError)throw bankError;if(ledgerError)throw ledgerError;if(issuanceError)throw issuanceError;if(emailError)throw emailError;
   setDepositEmailLogs(emailRows||[]);
   const txById=new Map(transactions.map(t=>[t.id,t]));
   const trustByTransaction=new Map((trustRows||[]).map(t=>[t.transaction_id,t]));
   const bankById=new Map((bankRows||[]).map(b=>[b.id,b]));
   const issuanceByTrustTransaction=new Map((issuanceRows||[]).map(row=>[row.trust_transaction_id,row]));
   // Build history from each posted ledger receipt, not one trust-details row per transaction.
   // A single property/trade may have several legitimate deposits.
   const history=(ledgerRows||[]).map(ledger=>{
    const tx=txById.get(ledger.transaction_id);if(!tx)return null;
    const trust=trustByTransaction.get(tx.id)||{};
    const bank=bankById.get(ledger.bank_account_id||trust.trust_bank_account_id||tx.trust_bank_account_id);
    const ledgerDate=String(ledger.ledger_date||ledger.created_at||"").slice(0,10);
    const amount=Number(ledger.amount||0);
    const receiptMeta=(trustRows||[]).find(row=>row.transaction_id===tx.id&&Number(row.amount||0)===amount&&String(row.deposit_date||row.created_at||"").slice(0,10)===ledgerDate&&String(row.received_from||"").trim().toLowerCase()===String(ledger.client_name||"").trim().toLowerCase())||trust;
    const issuance=issuanceByTrustTransaction.get(ledger.id)||{};
    return {...receiptMeta,...issuance,id:ledger.id,trust_transaction_id:ledger.id,ledger_transaction_id:tx.id,transaction_id:tx.id,transaction_number:tx.transaction_number||"—",property_address:[tx.property_address,tx.unit_number?"Unit "+tx.unit_number:"",tx.city,tx.province,tx.postal_code].filter(Boolean).join(", "),received_from:ledger.client_name||receiptMeta.received_from||"—",deposit_date:ledgerDate,created_at:ledger.created_at||receiptMeta.created_at,amount,reference_number:ledger.reference||receiptMeta.reference_number||"",payment_type:receiptMeta.payment_type||"—",trust_bank_account_id:ledger.bank_account_id||receiptMeta.trust_bank_account_id||tx.trust_bank_account_id,bank_name:bank?.name||"—",receipt_number:"DR-"+String(tx.transaction_number||tx.id).replace(/[^A-Za-z0-9-]/g,"")+( (ledgerRows||[]).filter(other=>other.transaction_id===tx.id).length>1?"-"+String(ledger.id).slice(0,6).toUpperCase():""),receipt_attachment_path:receiptMeta.receipt_attachment_path||null,receipt_attachment_name:receiptMeta.receipt_attachment_name||null,receipt_attachment_mime_type:receiptMeta.receipt_attachment_mime_type||null,posted:true};
   }).filter(Boolean);
   // Listing placeholder deposits may be mirrored to a later trade. Keep the trade receipt if both match.
   const signature=item=>[Number(item.amount||0).toFixed(2),String(item.deposit_date||item.created_at||"").slice(0,10),String(item.received_from||"").trim().toLowerCase(),String(item.reference_number||"").trim().toLowerCase()].join("|");
   const tradeDepositSignatures=new Set(history.filter(item=>!String(item.transaction_number||"").startsWith("LST-")).map(signature));
   setDepositHistory(history.filter(item=>!String(item.transaction_number||"").startsWith("LST-")||!tradeDepositSignatures.has(signature(item))));
  }catch(err){setDepositHistoryError(err?.message||"Could not load deposit history.");setDepositHistory([])}
  finally{setDepositHistoryLoading(false)}
 }
